import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro: ADR-0007 layer 3 — atom laws from measured bindings","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/layer3-loop.md","filePath":"vendored/graphopt/project/retros/layer3-loop.md"}`),a={name:`graphopt/project/retros/layer3-loop.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-adr-0007-layer-3-—-atom-laws-from-measured-bindings" tabindex="-1">Retro: ADR-0007 layer 3 — atom laws from measured bindings <a class="header-anchor" href="#retro-adr-0007-layer-3-—-atom-laws-from-measured-bindings" aria-label="Permalink to “Retro: ADR-0007 layer 3 — atom laws from measured bindings”">​</a></h1><p>Date: 2026-10-16 Branch: feat/runtime-loop Driver: <code>lab/mint/atom_law_loop.py</code> (new). Artifact: <code>project/retros/layer3-loop.json</code>.</p><p>Layer 1 minted definitional atoms (anti-unification); layer 2 minted handler bodies (<code>handler_synth</code>); this is the layer-3 half — <strong>an atom&#39;s law set synthesized from measured bindings</strong>, run as a closed loop over the three hand-built carrier atoms (<code>om_decayed</code>, <code>applyd</code>, <code>decay_vec</code>). The driver is one loop, not three: per candidate schema it enumerates measured environments (typed shape families x attr-domain products + the oracle&#39;s <code>_synth_sites</code> window + real corpus matches), scores the tri-state oracle outcome per env, mints guards (<code>auto_cond</code>, with a small axis/attr bank fallback for the carrier-attr corner its generic domain cannot reach) and attr derives (a solver-measured hook fitted by <code>synth_dspec_multi</code>), then certifies through <code>verify_law</code> — <code>derivable</code>/<code>subsumed-*</code> means the shipped library already implies it, <code>primitive</code> means a genuinely new measured-true candidate.</p><h2 id="the-applyd-slot-solve" tabindex="-1">The applyd slot solve <a class="header-anchor" href="#the-applyd-slot-solve" aria-label="Permalink to “The applyd slot solve”">​</a></h2><p><code>applyd(aff_diag(a,b), h) = a*h + b</code> is affine in <code>h</code>, so any LHS affine in the state slot decomposes <em>per env</em> as <code>L = (lhs(h+d) - lhs(h))/d</code>, <code>B = lhs(h) - L*h</code> (d drawn bounded from 0). Slot values are matched against the bounded expr bank and intersected across envs — the value-vector dedup of <code>dspec_synth</code> lifted to terms. This replaced the blind <code>e1 x e2</code> pair product: the true compose <code>(mul a1 a2, add (mul a1 b2) b1)</code> sat ~90k deep in diagonal pair order — the quartic-hang class — while the slot solve finds it in two passes of ~2.4k bank evals. The same solve recovers compose, add-merge, scale-absorb AND the matmul readout (<code>matmul(E, applyd(f,h)) = applyd(aff_diag(E@a, E@b), h)</code> — h broadcasts along the contracted axis so the Jacobian is diagonal in it).</p><h2 id="results-measured-all-serial" tabindex="-1">Results (measured, all serial) <a class="header-anchor" href="#results-measured-all-serial" aria-label="Permalink to “Results (measured, all serial)”">​</a></h2><table tabindex="0"><thead><tr><th>atom</th><th>candidates</th><th>certified rows</th><th>rejected</th></tr></thead><tbody><tr><td>applyd</td><td>5 schemas + 18 solved</td><td>18 (compose x8, addmerge x4, scale x4, readout, nobias) — scale[0] <code>subsumed-duplicate</code> via <code>xc_scale_applyd</code>, rest <code>primitive</code></td><td>1 (<code>addmerge_wrongstate</code>, deliberately false)</td></tr><tr><td>om_decayed</td><td>6</td><td>4 — unfold/refold subsumed (refold hits 16 real corpus sites), <code>absorb_score</code> primitive, <code>rowcat</code> guarded <code>(&#39;axis&#39;,&#39;d1&#39;,&#39;D&#39;,-2)</code> primitive</td><td>2 (<code>absorb_value</code>, <code>keycat_wrong</code>)</td></tr><tr><td>decay_vec</td><td>4</td><td>3 — <code>merge</code> 96/96 equal, <code>merge_synth</code> (dspec <em>withheld</em>; solver+synth_dspec_multi minted <code>O=O1+O2, S=S1+S2</code>), <code>unit_mul</code></td><td>1 (<code>merge_sign_s1</code>, deliberately wrong)</td></tr></tbody></table><p>Distinct new measured-true laws modulo commutative spellings: <code>affd.compose</code>, <code>affd.addmerge</code>, <code>affd.scale</code> (twin spellings), <code>affd.readout</code>, <code>affd.nobias</code>, <code>omd.absorb_score</code>, <code>omd.rowcat</code> (conditional), <code>dv.merge</code>, <code>dv.unit_mul</code>.</p><h2 id="the-measurement-caught-a-lowering-bug" tabindex="-1">The measurement caught a lowering bug <a class="header-anchor" href="#the-measurement-caught-a-lowering-bug" aria-label="Permalink to “The measurement caught a lowering bug”">​</a></h2><p><code>decay_vec</code>&#39;s executor read <code>sign = int(kw.get(&quot;sign&quot;, 1) or 1)</code> — <code>or 1</code> silently rewrites <code>sign=0</code> to 1, so <code>dv(g,T,o,0)</code> evaluated as <code>g^{k+o}</code> instead of the constant <code>g^o</code>. The oracle flagged <code>dv.unit_mul</code> <code>unequal</code> and the solver&#39;s (O,S) fits refused — the loop declined to mint rather than shipping a wrong law. Fixed (<code>sign = int(kw[&quot;sign&quot;]) if &quot;sign&quot; in kw else 1</code>); nothing shipped mints <code>sign=0</code>, so the fix is behavior-neutral on existing laws (256 carrier tests pass).</p><h2 id="honest-residuals" tabindex="-1">Honest residuals <a class="header-anchor" href="#honest-residuals" aria-label="Permalink to “Honest residuals”">​</a></h2><ul><li><code>auto_cond</code>&#39;s measured domain cannot reach attr-heavy carrier corners (concat dims, decay_vec attrs) — <code>omd.rowcat</code>&#39;s guard came from the driver&#39;s typed-env axis bank, marked in the note. The upstream fix is a domain override on <code>auto_cond_object</code>.</li><li>Real-site coverage is thin for carrier-internal patterns (corpus terms are pre-rewrite; <code>applyd</code>/<code>om_decayed</code> arise during search). <code>real=0</code> rows lean on synthesized envs — typed by construction, but a narrower claim than a corpus-measured firing.</li><li><code>verify=primitive</code> says &quot;not derivable by the shipped set&quot;, not &quot;should ship&quot; — cost/pay is unmeasured; admission is a separate gate (the mul_unsq_nat path).</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};